uint8_t tx_buffer[512];//can delete this, not needed
uint8_t rx_buffer[512];

uint8_t root_dir_buffer[512];
uint8_t song_sector_buffer[512];
uint8_t FAT_sector_buffer[512];

#define AUDIO_BUF_SAMPLES 8192                 // 16KB buffer, 8192 x 16bit samples
#define HALF (AUDIO_BUF_SAMPLES / 2)           // each half is 4096 samples = 16 sectors
int16_t audio_buf[AUDIO_BUF_SAMPLES];          // the buffer dma keeps looping over

// set inside the interrupt, read in main loop -> needs volatile or compiler ignores changes
volatile uint8_t refill_first_half = 0;
volatile uint8_t refill_second_half = 0;

// runs when dma hits the halfway point or the end of audio_buf
// keep this short!! just set a flag, the actual refilling happens in main
void DMA1_Stream5_IRQHandler(void){
	if (DMA1->HISR & DMA_HISR_HTIF5){      // first half finished playing
		DMA1->HIFCR = DMA_HIFCR_CHTIF5;    // clear flag or this keeps firing forever
		refill_first_half = 1;
	}
	if (DMA1->HISR & DMA_HISR_TCIF5){      // second half finished, dma wraps to the top
		DMA1->HIFCR = DMA_HIFCR_CTCIF5;
		refill_second_half = 1;
	}
}

// temporary: fills a half with the sine wave, will swap this for song data later
uint32_t sine_pos = 0;                     // where we are in the sine table (0-95)
void fill_half(int16_t *dst, uint32_t count){
	for (uint32_t i = 0; i < count; i++){
		dst[i] = SINE_TABLE_1KHZ_48K[sine_pos];
		sine_pos++;
		if (sine_pos == 96) sine_pos = 0;  // wrap so the wave carries on smoothly
	}
}

uint32_t fat_start;

uint32_t current_cluster;
uint32_t next_cluster;


void USART2_SendChar(char c){
	while (!(USART2->SR & (1U <<7 )));
	USART2->DR = c;
}

char USART2_ReceiveChar(void){
	while (!(USART2->SR & (1U <<5 )));
	return (char)USART2->DR;
}
void USART2_SendString(char *str){
	while (*str)
		USART2_SendChar(*str++);
}

// Retarget stdio printf to USART2
int _write(int file, char *ptr, int len)
{
    for (int i = 0; i < len; i++)
    {
        USART2_SendChar(ptr[i]);
    }
    return len;
}

//read a 2-byte little-endian number starting at the given address
uint16_t read16(uint8_t *buffer){
	return (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
}

//read a 4-byte little-endian number starting at the given address
uint32_t read32(uint8_t *buffer){
	return (uint32_t)buffer[0]
	     | ((uint32_t)buffer[1] << 8)
	     | ((uint32_t)buffer[2] << 16)
	     | ((uint32_t)buffer[3] << 24);
}

uint32_t fat_next_cluster(uint32_t cluster){

	uint32_t fat_sector = fat_start + cluster/128;//to find which sector of FAT the current cluster lies in, ie which page
	uint32_t sector_pos = (cluster % 128) * 4; //get remainder and then multiply with 4 bytes, cause each entry takes 4 bytes, ie which line in page

	 if (SD_Read_Single_Block(FAT_sector_buffer, fat_sector) != 0){
	        printf("FAT read error\r\n");
	        return 0x0FFFFFFF;          // treat an error as "end", so the loop stops
	    }
	    return read32(&FAT_sector_buffer[sector_pos]) & 0x0FFFFFFF;  // the next cluster is recorded here
	}




int main(void)
{
	RCC->AHB1ENR |= (1U << 0); //enabling clock GPIOA
	RCC->APB1ENR |= (1U << 17);//enabling  clock for USART2

	//clearing bits
	GPIOA->MODER &= ~((3U << 4) | (3U << 6));

	//setting mode to alternate function for USART2(PA2,3)
	GPIOA->MODER |= ((2U << 4) | (2U << 6));

	//selecting  AF as USART2
	GPIOA->AFR[0] &= ~((0xFU << 8) | (0xFU << 12));
	GPIOA->AFR[0] |= ((7U << 8) | (7U << 12));

	//set baud rate
	USART2->BRR |= 0x8B;

	//enabling usart and transmitter
	USART2->CR1 &= ~((1U << 3) | (1U << 13));
	USART2->CR1 |= ((1U << 3) | (1U << 13));
	//receiver
	USART2->CR1 &= ~(1U << 2);
	USART2->CR1 |= (1U << 2);

	printf("System Boot OK! SystemCoreClocks: %lu Hz\r\n", 16000000UL);

	SPI1_Init();
	if (SD_Init() != 0){
		while(1);
	}

	SPI1_Set_Fast();
	I2S3_Init();
	printf("DMA Started\r\n");

	// 1. read sector 0 from the card into rx_buffer
	if (SD_Read_Single_Block(rx_buffer, 0) != 0){
	    while(1);
	}
	// 2. pull values out of the bytes we just read
	uint32_t part_start = read32(&rx_buffer[454]);

	printf("Partition Start : %lu\r\n", part_start);

	if (SD_Read_Single_Block(rx_buffer, part_start) != 0){
			    while(1);
			}
	uint16_t bytes_per_sector    = read16(&rx_buffer[11]);  //bytes 11-12
	uint16_t sectors_per_cluster = rx_buffer[13];           //1 byte, no helper needed
	uint16_t reserved_sectors    = read16(&rx_buffer[14]);  //bytes 14-15
	uint16_t num_fats            = rx_buffer[16];           //1 byte
	uint32_t sectors_per_fats    = read32(&rx_buffer[36]);  //bytes 36-39
	uint32_t root_cluster        = read32(&rx_buffer[44]);  //bytes 44-47

	printf("Bytes Per Sector : %u\r\n", bytes_per_sector);
	printf("Sectors_Per_Cluster : %u\r\n", sectors_per_cluster);
	printf("Reserved Sectors : %u\r\n", reserved_sectors);
	printf("Number of FAT cluster maps : %u\r\n", num_fats);
	printf("Sectors Per FAT : %lu\r\n", sectors_per_fats);


	fat_start = part_start + reserved_sectors;
	uint32_t data_start = fat_start + (num_fats * sectors_per_fats);

	printf("Data Starts @: %lu\r\n", data_start);
	printf("Root Cluster: %lu\r\n", root_cluster);

	uint32_t root_sector = data_start + (root_cluster - 2) * sectors_per_cluster;


	if (SD_Read_Single_Block(root_dir_buffer, root_sector) != 0){
				    while(1);
				}

	for (int i = 0; i < 16; i++){
	    uint8_t *card = &root_dir_buffer[32 * i];

	    if (card[0] == 0x00){//card[0] is a way to go through the addresses, eg: card[1] here means card address + 1 byte | also if card[0] = 0 then that means empty ard, skip
	        break;
	    }
	    printf("Card:%d | First Byte:%X | Name: %.11s | Attribute: 0x%02X\r\n",
	           i, card[0], (char *)card, card[11]);
		if (memcmp(card, "TRACK01 WAV", 11) == 0){
			uint16_t hi = read16(&card[20]);  //high half of first cluster
			uint16_t lo = read16(&card[26]);  //low half of first cluster
			uint32_t cluster_number = ((uint32_t)hi << 16) | lo;
			printf("Track 01 found @ cluster %lu\r\n", cluster_number);
			uint32_t sector = data_start + (cluster_number - 2) * sectors_per_cluster;
			printf("Track 01 starts @ Sector %lu\r\n", sector);
			if (SD_Read_Single_Block(song_sector_buffer, sector) != 0){
						    while(1);
						}
			printf("Byte 0-3 is: %.4s\r\n", (char *)song_sector_buffer);//this is just a test, get rid of it
			printf("Format: %.4s\r\n", (char *)&song_sector_buffer[8]);
			printf("Audio Format(1 means uncompressed): %i\r\n", read16(&song_sector_buffer[20]));
			printf("No: of Channels(1- mono, 2- stereo): %i\r\n", read16(&song_sector_buffer[22]));
			printf("Sample Rate: %lu\r\n", read32(&song_sector_buffer[24]));
			printf("Bit Per Sample: %i\r\n",read16(&song_sector_buffer[34]));
			printf("Data Size: %lu\r\n",read32(&song_sector_buffer[40]));

			printf("Data Size read from cards: %lu\r\n",read32(&card[28]));
			printf("File size from WAV Header: %lu\r\n",read32(&song_sector_buffer[4]));

			current_cluster = cluster_number;
			uint32_t count = 0;
			while(current_cluster < 0x0FFFFFF8){//either not reached end of a chain or no error
				next_cluster = fat_next_cluster(current_cluster);
				count++;
				current_cluster = next_cluster;
			}
			printf("TRACK01 WAV uses %lu clusters\r\n", count);


		}
		/*if (memcmp(card, "TRACK02 WAV", 11) == 0){
			uint16_t hi = read16(&card[20]);
			uint16_t lo = read16(&card[26]);
			uint32_t cluster_number = ((uint32_t)hi << 16) | lo;
			printf("Track 02 found @ cluster %lu\r\n", cluster_number);
		}*/
	}


	// start dma AFTER the fat stuff, so the card reading cant hold up the refills
	fill_half(&audio_buf[0], HALF);        // fill both halves before starting
	fill_half(&audio_buf[HALF], HALF);
	Audio_DMA_Start(audio_buf, AUDIO_BUF_SAMPLES);
	printf("DMA started with two halves\r\n");

	uint32_t refills = 0, next_print = 215; // ~21.5 refills a sec, so print every ~10s
	while (1){
		if (refill_first_half){            // dma is now playing 2nd half, safe to refill 1st
			refill_first_half = 0;
			fill_half(&audio_buf[0], HALF);
			refills++;
		}
		if (refill_second_half){           // dma wrapped back to 1st half, refill 2nd
			refill_second_half = 0;
			fill_half(&audio_buf[HALF], HALF);
			refills++;
		}
		if (refills >= next_print){
			printf("Refills: %lu\r\n", refills);
			next_print += 215;
		}
	}

}
